const app=document.querySelector('#app'),$=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
let library=window.IELTS_LIBRARY||[],custom=read('ielts-library',[]),history=read('ielts-history',[]),subject='listening',book='all',search='',mode='practice',view='home',session=null,partIndex=0,clock=null,audio=null,audioURL='',audioName='',sourceView='original',largeText=false;
function store(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('浏览器存储空间不足，请导出记录备份');return false}}
function toast(t){let e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(toast.id);toast.id=setTimeout(()=>e.style.display='none',3500)}
