function header(){return `<header><div class="brand"><span class="logo">i.</span><div>IELTS LAB<small>雅思机考练习室</small></div></div><nav class="nav"><button data-home class="${view==='home'?'active':''}">真题题库</button><button data-history class="${view==='history'?'active':''}">练习记录</button><button data-import>导入题库 ↗</button></nav><span class="avatar">同学</span></header><input class="hidden" type="file" id="import-file" accept=".json">`}
