function home(){view='home';let tests=allTests().filter(t=>t.type===subject&&(book==='all'||String(t.book)===book)&&(!search||t.title.toLowerCase().includes(search.toLowerCase())));let done=history.filter(h=>h.type===subject),books=[...new Set(library.map(t=>t.book))].sort((a,b)=>a-b);let graded=done.filter(h=>h.graded>0);app.innerHTML=header()+`<main><section class="hero"><div><span class="eyebrow">YOUR PERSONAL IELTS LIBRARY</span><h1>你的真题，<br>你的机考练习室。</h1><p>听力与阅读真题已接入，保留原文、表格和地图。<br>在熟悉的答题环境里，专注每一次进步。</p><button class="primary" id="quick">开始${subject==='listening'?'听力':'阅读'}练习　→</button> <span class="muted">计时答题 · 自动保存</span></div><div class="hero-art"><div class="exam-mini"><span class="eyebrow">CAMBRIDGE IELTS COLLECTION</span><h3>${library.length} 套听力与阅读练习</h3><div class="lines"></div><div class="lines"></div><div class="lines"></div><span class="tag">原题保真　·　在线答题</span></div><div class="floating">✦　一步一步，接近目标</div></div></section><div class="layout"><section class="card"><div class="tabs"><button data-subject="listening" class="${subject==='listening'?'active':''}">♬　听力 Listening</button><button data-subject="reading" class="${subject==='reading'?'active':''}">▤　阅读 Reading</button></div><div class="section-title"><b>真题题库 <span class="muted"> / ${tests.length} 套</span></b><input id="search" class="answer" style="width:210px" placeholder="搜索试卷名称" value="${escapeHTML(search)}"></div><div class="filters"><button class="chip ${book==='all'?'active':''}" data-book="all">全部</button>${books.map(b=>`<button class="chip ${book===String(b)?'active':''}" data-book="${b}">剑雅 ${b}</button>`).join('')}</div><div class="filters"><button class="chip ${mode==='practice'?'active':''}" data-mode="practice">自由练习</button><button class="chip ${mode==='exam'?'active':''}" data-mode="exam">限时模考</button><span class="muted" style="padding:6px">${subject==='listening'?'4 Parts · 30 分钟':'3 Passages · 60 分钟'}</span></div><div class="test-grid">${tests.map(t=>`<article class="test-card"><div class="test-top"><div class="test-icon">${subject==='listening'?'♬':'▤'}</div><div><h3>${escapeHTML(t.title)}</h3><span class="tag">${escapeHTML(t.quality||'已导入')}</span> <span class="tag">${subject==='listening'?'Listening':t.category==='G'?'General Training':'Academic Reading'}</span></div></div><p>${t.parts.length} 个题组　·　${t.parts.reduce((n,p)=>n+p.questions.length,0)} 道题　·　${t.duration} 分钟</p><div class="test-bottom"><span class="muted">${read('session-'+t.id,null)?'已有进度 · 可继续':t.parts.every(p=>p.questions.every(q=>q.answer!=null))?'已接入答案核对':'部分答案待核对'}</span><button class="link" data-start="${escapeHTML(t.id)}">进入练习 →</button></div></article>`).join('')||'<div class="empty">没有匹配的试卷</div>'}</div><div class="hint">真题采用「原题内容 + 在线答题卡」形式，图表题保留原图。文字识别版本可辅助阅读，请以原页为准。</div></section><aside class="side"><section class="card"><div class="side-title">我的学习进度</div><div class="stats"><div><b>${done.length}</b><span>已完成练习</span></div><div><b>${graded.length?Math.round(graded.reduce((n,h)=>n+h.correct/h.graded,0)/graded.length*100):'—'}<small style="font-size:12px">${graded.length?'%':''}</small></b><span>已核对题正确率</span></div></div><div class="hint">数据保存在当前浏览器。结果页可导出记录备份。</div></section><section class="card"><div class="side-title">素材导入状态</div><p class="muted">${books.map(b=>'剑雅 '+b).join('、')} 已整理入库。</p><div class="hint">其余下载中的文件无法解析。剑雅 15 的源 Word 含全黑题图，未加入可练题库。</div><button class="link" id="report" style="margin-top:14px">查看文件检查报告 ↗</button></section><section class="card"><div class="side-title">我的听力音频</div><p class="muted">进入听力试卷后选择对应录音。音频不上传，刷新页面后需重新选择。</p><label class="upload" id="import-label">＋ 导入更多题库</label><button id="template" class="link" style="font-size:12px">下载题库格式示例 ↓</button></section></aside></div></main><footer>IELTS LAB · 个人真题练习　｜　仅听力与阅读 · 浏览器本地保存</footer>`;bindHeader();document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;home()});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{book=b.dataset.book;home()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;home()});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(allTests().find(t=>t.id===b.dataset.start)));$('#quick').onclick=()=>tests[0]?start(tests[0]):toast('请先选择有试卷的分类');$('#search').onchange=e=>{search=e.target.value;home()};$('#import-label').onclick=()=>$('#import-file').click();$('#template').onclick=()=>download('ielts-template.json',JSON.stringify({title:'我的试卷',type:subject,duration:subject==='listening'?30:60,parts:[{title:'Part 1',passage:'在这里填写原文',instructions:'Write ONE WORD ONLY.',questions:[{prompt:'题目内容',type:'text',answer:'answer'}]}]},null,2));$('#report').onclick=()=>window.open('import-report.html','_blank')}
async function importFile(e){try{const t=JSON.parse(await e.target.files[0].text());if(!['listening','reading'].includes(t.type)||typeof t.title!=='string'||!Number.isFinite(t.duration)||t.duration<=0||!Array.isArray(t.parts)||!t.parts.length)throw Error('请参照模板填写 title、type、duration、parts');let n=0;t.parts.forEach(p=>{if(typeof p.title!=='string'||!Array.isArray(p.questions)||!p.questions.length)throw Error('题组须包含标题与题目');delete p.sourceHtml;p.questions.forEach(q=>{n++;if(typeof q.prompt!=='string'||!['text','choice','boolean'].includes(q.type)||!(typeof q.answer==='string'||Array.isArray(q.answer))||(q.type==='choice'&&!Array.isArray(q.options)))throw Error('题目格式不正确')})});if(n>100)throw Error('每套试卷最多 100 题');delete t.keyHtml;t.id='import-'+Date.now();custom.push(t);store('ielts-library',custom);subject=t.type;book='all';home();toast('已导入到当前浏览器')}catch(err){toast('导入失败：'+err.message)}}
function test(){return allTests().find(t=>t.id===session.testId)}
function offset(i){return test().parts.slice(0,i).reduce((n,p)=>n+p.questions.length,0)}
function start(t){if(!t)return;stop();audio?.pause();let old=read('session-'+t.id,null);session=old&&old.testId===t.id?old:{testId:t.id,answers:{},flags:{},remaining:t.duration*60,mode,deadline:Date.now()+t.duration*60000,paused:false};if(old&&!old.testId){session={testId:t.id,answers:old.answers||{},flags:old.flags||{},remaining:old.remaining||t.duration*60,mode:old.mode||mode,deadline:Date.now()+(old.remaining||t.duration*60)*1000,paused:false}}partIndex=0;sourceView='original';view='exam';renderExam();clock=setInterval(()=>{if(view!=='exam'||session.paused)return;if(session.mode==='practice')session.remaining=Math.max(0,session.remaining-1);$('#timer').textContent=time(remaining());save();if(!remaining()&&session.mode==='exam')finish(true)},1000);if(!remaining()&&session.mode==='exam')finish(true)}
function source(p){if(sourceView==='text'&&p.passage)return `<div class="hint">文字识别仅供辅助，图表及可疑文字请切回原页核对。</div><div class="extracted-text">${escapeHTML(p.passage)}</div>`;if(p.sourceHtml)return `<div class="source-doc">${p.sourceHtml}</div>`;if(p.sourceImages?.length)return p.sourceImages.map((u,i)=>`<figure class="source-page"><figcaption>原文件第 ${p.sourcePages?.[i]||i+1} 页 · 点击查看大图</figcaption><a href="${escapeHTML(u)}" target="_blank" rel="noopener"><img loading="lazy" src="${escapeHTML(u)}" alt="${escapeHTML(p.title)} 原题第${i+1}页"></a></figure>`).join('');return `<div class="extracted-text">${escapeHTML(p.passage||'')}</div>`}
function renderExam(){let t=test(),p=t.parts[partIndex],off=offset(partIndex),list=t.type==='listening',total=t.parts.reduce((n,p)=>n+p.questions.length,0);app.innerHTML=`<header class="exam-header"><div class="brand"><span class="logo">i.</span>IELTS LAB</div><div><b>${escapeHTML(t.title)}</b> <span class="muted">${list?'Listening':'Reading'} · ${session.mode==='exam'?'限时模考':'自由练习'}</span></div><div class="exam-info"><span class="timer" id="timer">${time(remaining())}</span>${session.mode==='practice'?`<button class="secondary" id="pause">${session.paused?'继续':'暂停'}</button>`:''}<button id="exit" class="secondary">保存退出</button><button id="submit" class="primary">交卷</button></div></header><div class="toolbar"><b>${list?'Part':'Passage'} ${partIndex+1}</b><span class="muted">Questions ${off+1}–${off+p.questions.length}</span><div class="spacer"></div><button id="original" class="chip ${sourceView==='original'?'active':''}">原题</button><button id="text" class="chip ${sourceView==='text'?'active':''}" ${!p.passage?'disabled':''}>文字</button><button id="font" class="secondary">Aa 字号</button><button id="highlight" class="secondary">高亮</button></div><section class="exam-body ${largeText?'large-text':''}"><article class="passage" id="passage">${list?`<div class="audio-panel"><b>♬ 本地听力音频</b><span class="muted">　${escapeHTML(audioName||'尚未选择音频')}</span><div id="audio-mount"></div><label class="upload">＋ 选择 / 更换对应录音<input type="file" id="audio-file" accept="audio/*"></label></div>`:''}<h2>${escapeHTML(p.title)}</h2>${source(p)}</article><section class="questions"><div class="section-title"><h3>Questions ${off+1}–${off+p.questions.length}</h3><span class="muted" id="save-status">自动保存已开启</span></div><p class="muted">${escapeHTML(p.instructions||'Answer the questions below.')}</p>${session.paused?'<div class="pause-cover">练习已暂停，点击顶部「继续」恢复答题。</div>':''}${p.questions.map((q,j)=>{let n=off+j+1,a=session.answers[n]||'',disabled=session.paused?'disabled':'';return `<div class="question" id="q-${n}"><div class="q-head"><b>${n}. ${escapeHTML(q.prompt)}</b><button class="flag ${session.flags[n]?'on':''}" data-flag="${n}" aria-label="标记第${n}题">⚑</button></div>${q.type==='text'?`<input class="answer" aria-label="第${n}题答案" data-answer="${n}" value="${escapeHTML(a)}" placeholder="输入答案 / 选项字母" autocomplete="off" ${disabled}>`:`<div class="options">${(q.type==='boolean'?['TRUE','FALSE','NOT GIVEN']:q.options).map((o,k)=>{let v=q.type==='boolean'?o:String.fromCharCode(65+k);return `<label><input type="radio" name="q${n}" data-answer="${n}" value="${escapeHTML(v)}" ${a===v?'checked':''} ${disabled}> ${q.type==='choice'?v+'. ':''}${escapeHTML(o)}</label>`}).join('')}</div>`}</div>`}).join('')}</section></section><div class="exam-footer"><div class="part-tabs">${t.parts.map((p,i)=>`<button class="secondary ${partIndex===i?'active':''}" data-part="${i}">${list?'Part':'Passage'} ${i+1}</button>`).join('')}</div><div class="q-nav">${Array.from({length:total},(_,i)=>`<button aria-label="跳转第${i+1}题" class="q-num ${session.answers[i+1]?.trim()?'answered':''} ${session.flags[i+1]?'flagged':''}" data-jump="${i+1}">${i+1}</button>`).join('')}</div><span class="muted" id="progress">${Object.values(session.answers).filter(a=>a.trim()).length}/${total} 已答</span></div>`;
$('#exit').onclick=exit;$('#submit').onclick=()=>submitDialog();$('#pause')?.addEventListener('click',()=>{session.paused=!session.paused;if(session.paused)audio?.pause();save();renderExam()});$('#original').onclick=()=>{sourceView='original';renderExam()};$('#text').onclick=()=>{sourceView='text';renderExam()};$('#font').onclick=()=>{largeText=!largeText;renderExam()};$('#highlight').onclick=()=>{let sel=window.getSelection();if(!sel.rangeCount||!sel.toString())return toast('在文字版本中选中一段文字，再点击高亮');let r=sel.getRangeAt(0);if(!$('#passage').contains(r.commonAncestorContainer))return toast('请选择左侧文章内容');try{r.surroundContents(document.createElement('mark'));sel.removeAllRanges()}catch{toast('请在同一段内选择文字')}};
document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{partIndex=+b.dataset.part;renderExam()});document.querySelectorAll('[data-answer]').forEach(e=>e.addEventListener(e.type==='radio'?'change':'input',()=>{session.answers[e.dataset.answer]=e.value;save();$(`[data-jump="${e.dataset.answer}"]`).classList.toggle('answered',!!e.value.trim());$('#progress').textContent=Object.values(session.answers).filter(v=>v.trim()).length+'/'+total+' 已答';$('#save-status').textContent='✓ 已自动保存'}));document.querySelectorAll('[data-flag]').forEach(b=>b.onclick=()=>{let n=b.dataset.flag;session.flags[n]=!session.flags[n];save();b.classList.toggle('on',session.flags[n]);$(`[data-jump="${n}"]`).classList.toggle('flagged',session.flags[n])});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{let n=+b.dataset.jump,pi=t.parts.findIndex((p,i)=>n>offset(i)&&n<=offset(i)+p.questions.length);if(pi!==partIndex){partIndex=pi;renderExam()}$('#q-'+n).scrollIntoView({behavior:'smooth',block:'center'});$('#q-'+n+' input')?.focus({preventScroll:true})});
if(list){if(audio)$('#audio-mount').append(audio);$('#audio-file').onchange=e=>{const f=e.target.files[0];if(!f)return;audio?.pause();if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(f);audioName=f.name;audio=document.createElement('audio');audio.controls=true;audio.src=audioURL;audio.onerror=()=>toast('音频无法播放，请尝试 MP3 或 WAV 文件');renderExam()}}}
function submitDialog(){let total=test().parts.flatMap(p=>p.questions).length,filled=Object.values(session.answers).filter(a=>a.trim()).length;let d=document.createElement('dialog');d.className='submit-dialog';d.innerHTML=`<h2>确认交卷？</h2><p>已完成 ${filled}/${total} 题${filled<total?`，还有 ${total-filled} 题未答`:''}。</p><p class="muted">交卷后可查看参考答案和本次作答记录。</p><div class="dialog-actions"><button class="secondary" id="cancel-submit">继续答题</button><button class="primary" id="confirm-submit">确认交卷</button></div>`;document.body.append(d);d.showModal();d.querySelector('#cancel-submit').onclick=()=>d.remove();d.querySelector('#confirm-submit').onclick=()=>{d.remove();finish(false)}}
function normalize(a){let s=String(a??'').normalize('NFKC').trim().toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ');return ({t:'true',f:'false',ng:'not given',y:'yes',n:'no'})[s]||s}
function variants(a){if(Array.isArray(a))return a.flatMap(variants);let result=[];for(let item of String(a??'').split(/\s*\/\s*/)){let m=item.match(/\(([^()]*)\)/);if(m){let before=item.slice(0,m.index),after=item.slice(m.index+m[0].length);result.push(...variants(before+after),...variants(before+m[1]+after))}else result.push(normalize(item))}return [...new Set(result)].filter(Boolean)}
function grade(t,answers){let rows=t.parts.flatMap(p=>p.questions).map((q,i)=>{let a=answers[i+1]||'',known=q.answer!=null&&variants(q.answer).length>0;return {n:i+1,prompt:q.prompt,yours:a,answer:Array.isArray(q.answer)?q.answer.join(' / '):q.answer,correct:known?!!a.trim()&&variants(q.answer).includes(normalize(a)):null}});for(const g of t.groups||[]){let expected=g.answers.map(normalize),used=new Set();for(const n of g.numbers){let r=rows[n-1],v=normalize(r.yours),i=expected.findIndex((a,j)=>a===v&&!used.has(j));r.correct=i>=0;if(i>=0)used.add(i);r.answer=g.answers.join(' / ')+'（同组不计顺序，各选项只计一次）'}}return rows}
function finish(auto){stop();audio?.pause();let t=test(),rows=grade(t,session.answers),h={id:'result-'+Date.now(),testId:t.id,title:t.title,type:t.type,date:new Date().toISOString(),total:rows.length,graded:rows.filter(r=>r.correct!==null).length,correct:rows.filter(r=>r.correct===true).length,rows,auto};history.unshift(h);history=history.slice(0,100);store('ielts-history',history);localStorage.removeItem('session-'+t.id);showResult(h)}
function showResult(h){view='result';let t=allTests().find(t=>t.id===h.testId),graded=h.graded??h.total;app.innerHTML=header()+`<main class="result"><div class="card"><div class="score"><span class="eyebrow">PRACTICE COMPLETE</span><h2>${escapeHTML(h.title)}</h2><strong>${h.correct}<span class="muted" style="font-size:24px"> / ${graded} 已核对</span></strong><p>共 ${h.total} 题 · ${h.total-graded} 题待核对${h.auto?' · 时间结束自动交卷':''}</p><p class="muted">核对结果仅供练习；不换算官方分数。文本题支持答案中的可选词和拼写变体。</p><p><button class="primary" data-home>返回题库</button> <button class="secondary" id="export">导出作答记录</button> <button class="secondary" id="retry">重新练习</button></p></div>${t?.keyImages?.length||t?.keyHtml?`<details class="key-reference"><summary>展开原文件参考答案（用于人工核对）</summary>${(t.keyImages||[]).map(u=>`<img class="key-image" src="${escapeHTML(u)}" alt="原文件答案页">`).join('')}${t.keyHtml||''}</details>`:''}<div class="result-row muted"><span>题号</span><span>我的答案</span><span>参考答案</span></div>${h.rows.map(r=>`<div class="result-row"><b class="${r.correct===true?'correct':r.correct===false?'incorrect':'muted'}">${r.correct===true?'✓':r.correct===false?'×':'?'} ${r.n}</b><span>${escapeHTML(r.yours)||'未作答'}</span><div><span class="${r.correct===null?'muted':'correct'}">${escapeHTML(r.answer)||'答案待确认，请查看原文件参考答案'}</span>${r.correct===null?`<div><button class="chip" data-manual="${r.n}" data-value="yes">核对为正确</button> <button class="chip" data-manual="${r.n}" data-value="no">核对为错误</button></div>`:''}</div></div>`).join('')}</div></main>`;bindHeader();$('#export').onclick=()=>download('ielts-result.json',JSON.stringify(h,null,2));$('#retry').onclick=()=>t?start(t):toast('未找到这套试卷');document.querySelectorAll('[data-manual]').forEach(b=>b.onclick=()=>{h.rows[+b.dataset.manual-1].correct=b.dataset.value==='yes';h.graded=h.rows.filter(r=>r.correct!==null).length;h.correct=h.rows.filter(r=>r.correct===true).length;store('ielts-history',history);showResult(h)})}
function showHistory(){view='history';app.innerHTML=header()+`<main><div class="card"><h2>练习记录</h2><p class="muted">保存在当前浏览器，结果页可导出备份。</p>${history.length?history.map((h,i)=>`<div class="history-row"><div><b>${escapeHTML(h.title)}</b><div class="muted">${new Date(h.date).toLocaleString('zh-CN')} · ${h.type==='listening'?'听力':'阅读'}</div></div><button class="link" data-result="${i}">${h.correct}/${h.graded??h.total} 已核对　查看结果 →</button></div>`).join(''):'<div class="empty">还没有完成的练习。</div>'}</div></main>`;bindHeader();document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(history[+b.dataset.result]))}
window.addEventListener('beforeunload',save);
